        (new InventoryCostingService($this->access,$this->now()))->correction($actor,$posted);
        if($p['type']==='stock'&&$p['stock_basis']==='actual_return')$this->access->repo->run("INSERT INTO finance_claims(scope,identity_hash,event_id) VALUES('purchase_return',?,?)",[$hash,$posted]);$event=$this->event($actor,'pc_approved',$id,['posted_id'=>$posted,'reason'=>$reason,'stock_movement_id'=>$movement]);return ['id'=>$id,'event_id'=>$event];
    }
    private function sourceAction(int $actor,string $action,array $in):array{
